 namespace JADED.Quantum {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Measurement;
    open Microsoft.Quantum.Math;
    open Microsoft.Quantum.Convert;
    open Microsoft.Quantum.Arrays;
    open Microsoft.Quantum.Preparation;
    open Microsoft.Quantum.Diagnostics;

    operation ApplyHadamardGate(qubit : Qubit) : Unit is Adj + Ctl {
        H(qubit);
    }

    operation ApplyPauliX(qubit : Qubit) : Unit is Adj + Ctl {
        X(qubit);
    }

    operation ApplyPauliY(qubit : Qubit) : Unit is Adj + Ctl {
        Y(qubit);
    }

    operation ApplyPauliZ(qubit : Qubit) : Unit is Adj + Ctl {
        Z(qubit);
    }

    operation ApplyCNOT(control : Qubit, target : Qubit) : Unit is Adj + Ctl {
        CNOT(control, target);
    }

    operation ApplyToffoli(control1 : Qubit, control2 : Qubit, target : Qubit) : Unit is Adj + Ctl {
        CCNOT(control1, control2, target);
    }

    operation ApplyPhaseGate(theta : Double, qubit : Qubit) : Unit is Adj + Ctl {
        R1(theta, qubit);
    }

    operation ApplyRotationX(theta : Double, qubit : Qubit) : Unit is Adj + Ctl {
        Rx(theta, qubit);
    }

    operation ApplyRotationY(theta : Double, qubit : Qubit) : Unit is Adj + Ctl {
        Ry(theta, qubit);
    }

    operation ApplyRotationZ(theta : Double, qubit : Qubit) : Unit is Adj + Ctl {
        Rz(theta, qubit);
    }

    operation SwapReverseRegister(register : Qubit[]) : Unit is Adj + Ctl {
        let numQubits = Length(register);
        for i in 0 .. (numQubits / 2 - 1) {
            SWAP(register[i], register[numQubits - 1 - i]);
        }
    }

    operation GroverOracle(markedState : Int, register : Qubit[]) : Unit is Adj + Ctl {
        use ancilla = Qubit();
        within {
            X(ancilla);
            H(ancilla);
        } apply {
            ApplyControlledOnInt(markedState, X, register, ancilla);
        }
        Reset(ancilla);
    }

    operation GroverDiffusionOperator(register : Qubit[]) : Unit is Adj + Ctl {
        let n = Length(register);
        within {
            ApplyToEachA(H, register);
            ApplyToEachA(X, register);
        } apply {
            Controlled Z(Most(register), register[n - 1]);
        }
    }

    operation GroverSearch(numQubits : Int, markedState : Int) : Result[] {
        use register = Qubit[numQubits];
        ApplyToEach(H, register);
        let numStates = PowI(2, numQubits);
        let iterations = Round(PI() / 4.0 * Sqrt(IntAsDouble(numStates)));
        for _ in 1 .. iterations {
            GroverOracle(markedState, register);
            GroverDiffusionOperator(register);
        }
        let results = MultiM(register);
        ResetAll(register);
        return results;
    }

    operation VQEAnsatz(parameters : Double[], register : Qubit[]) : Unit is Adj + Ctl {
        let numQubits = Length(register);
        let numParams = Length(parameters);
        for i in 0 .. numQubits - 1 {
            Ry(parameters[i % numParams], register[i]);
        }
        for i in 0 .. numQubits - 2 {
            CNOT(register[i], register[i + 1]);
        }
        for i in 0 .. numQubits - 1 {
            let idx = (numQubits + i) % numParams;
            Ry(parameters[idx], register[i]);
        }
    }

    operation MeasureEnergy(
        hamiltonian : Double[],
        ansatz : (Double[], Qubit[] => Unit is Adj + Ctl),
        parameters : Double[],
        numQubits : Int
    ) : Double {
        mutable totalEnergy = 0.0;
        let numSamples = 1000;
        for _ in 1 .. numSamples {
            use register = Qubit[numQubits];
            ansatz(parameters, register);
            let measurements = MultiM(register);
            mutable energy = 0.0;
            for i in 0 .. Length(hamiltonian) - 1 {
                if i < Length(measurements) and measurements[i] == One {
                    set energy = energy - hamiltonian[i];
                } else {
                    set energy = energy + hamiltonian[i];
                }
            }
            set totalEnergy += energy;
            ResetAll(register);
        }
        return totalEnergy / IntAsDouble(numSamples);
    }

    operation QuantumFourierTransform(register : Qubit[]) : Unit is Adj + Ctl {
        let numQubits = Length(register);
        for i in 0 .. numQubits - 1 {
            H(register[i]);
            for j in i + 1 .. numQubits - 1 {
                let angle = 2.0 * PI() / IntAsDouble(PowI(2, j - i + 1));
                Controlled R1([register[j]], (angle, register[i]));
            }
        }
        SwapReverseRegister(register);
    }

    operation PhaseEstimation(
        unitary : (Qubit[] => Unit is Adj + Ctl),
        eigenstate : Qubit[],
        precision : Int
    ) : Result[] {
        use control = Qubit[precision];
        // Standard QPE: prepare control in |+>
        ApplyToEach(H, control);
        for i in 0 .. precision - 1 {
            let power = PowI(2, i);
            for _ in 1 .. power {
                Controlled unitary([control[i]], eigenstate);
            }
        }
        Adjoint QuantumFourierTransform(control);
        let results = MultiM(control);
        ResetAll(control);
        return results;
    }

    operation QuantumAmplitudeEstimation(
        oracle : (Qubit[] => Unit is Adj + Ctl),
        numQubits : Int,
        precision : Int
    ) : Double {
        use register = Qubit[numQubits];
        use control = Qubit[precision];

        operation StatePreparation(target : Qubit[]) : Unit is Adj + Ctl {
            ApplyToEach(H, target);
        }

        operation GroverOperator(target : Qubit[]) : Unit is Adj + Ctl {
            oracle(target);
            Adjoint StatePreparation(target);
            GroverDiffusionOperator(target);
            StatePreparation(target);
        }

        // Prepare initial state
        StatePreparation(register);
        ApplyToEach(H, control);

        for i in 0 .. precision - 1 {
            let power = PowI(2, i);
            for _ in 1 .. power {
                Controlled GroverOperator([control[i]], register);
            }
        }

        Adjoint QuantumFourierTransform(control);
        let measurements = MultiM(control);
        mutable y = 0.0;
        for i in 0 .. precision - 1 {
            if measurements[i] == One {
                set y += IntAsDouble(PowI(2, i));
            }
        }
        let m = IntAsDouble(PowI(2, precision));
        let theta = y * PI() / m;

        ResetAll(register);
        ResetAll(control);

        return PowD(Sin(theta), 2.0);
    }

    operation ProteinFoldingCircuit(sequence : Int[], numQubits : Int) : Result[] {
        use register = Qubit[numQubits];
        ApplyToEach(H, register);
        for i in 0 .. Length(sequence) - 1 {
            let aminoAcid = sequence[i];
            let qubitIdx = i % numQubits;
            if aminoAcid % 2 == 0 {
                X(register[qubitIdx]);
            }
            if aminoAcid % 3 == 0 {
                Ry(IntAsDouble(aminoAcid) * 0.1, register[qubitIdx]);
            }
            if qubitIdx < numQubits - 1 {
                CNOT(register[qubitIdx], register[qubitIdx + 1]);
            }
        }
        for i in 0 .. numQubits - 2 {
            CNOT(register[i], register[i + 1]);
        }
        ApplyToEach(H, register);
        let results = MultiM(register);
        ResetAll(register);
        return results;
    }

    operation QuantumMachineLearning(
        trainingData : Double[][],
        labels : Int[],
        numQubits : Int,
        numLayers : Int
    ) : Double[] {
        mutable weights = ConstantArray(numQubits * numLayers, 0.1);
        let learningRate = 0.01;
        let epochs = 100;
        let numSamples = 100;

        operation PrepareState(features : Double[], reg : Qubit[]) : Unit {
            for q in 0 .. numQubits - 1 {
                let feature = features[q % Length(features)];
                Ry(feature, reg[q]);
            }
        }

        operation Ansatz(currentW : Double[], reg : Qubit[]) : Unit {
            for layer in 0 .. numLayers - 1 {
                for q in 0 .. numQubits - 1 {
                    let idx = layer * numQubits + q;
                    Ry(currentW[idx], reg[q]);
                }
                for q in 0 .. numQubits - 2 {
                    CNOT(reg[q], reg[q + 1]);
                }
            }
        }

        operation GetPrediction(features : Double[], currentW : Double[]) : Double {
            mutable countOne = 0;
            for _ in 1 .. numSamples {
                use reg = Qubit[numQubits];
                PrepareState(features, reg);
                Ansatz(currentW, reg);
                if M(reg[0]) == One {
                    set countOne += 1;
                }
                ResetAll(reg);
            }
            return IntAsDouble(countOne) / IntAsDouble(numSamples);
        }

        for _ in 1 .. epochs {
            for p in 0 .. Length(weights) - 1 {
                let shift = PI() / 2.0;
                let wPlus = weights w/ p <- weights[p] + shift;
                let wMinus = weights w/ p <- weights[p] - shift;
                mutable lPlus = 0.0;
                mutable lMinus = 0.0;
                for idx in 0 .. Length(trainingData) - 1 {
                    let probP = GetPrediction(trainingData[idx], wPlus);
                    let probM = GetPrediction(trainingData[idx], wMinus);
                    let lab = IntAsDouble(labels[idx]);
                    set lPlus += PowD(probP - lab, 2.0);
                    set lMinus += PowD(probM - lab, 2.0);
                }
                let grad = (lPlus - lMinus) / 2.0;
                set weights w/ p <- weights[p] - learningRate * grad;
            }
        }
        return weights;
    }

    operation HybridQuantumClassical(
        inputData : Double[],
        classicalWeights : Double[],
        quantumWeights : Double[]
    ) : Int {
        let numQubits = Length(quantumWeights);
        use register = Qubit[numQubits];
        for i in 0 .. numQubits - 1 {
            Ry(inputData[i % Length(inputData)] * quantumWeights[i] + classicalWeights[i % Length(classicalWeights)], register[i]);
        }
        for i in 0 .. numQubits - 2 {
            CNOT(register[i], register[i + 1]);
        }
        let result = M(register[0]);
        ResetAll([register]);
        return if result == One then 1 else 0;
    }

    operation EntanglementCircuit(numQubits : Int) : Result[] {
        use register = Qubit[numQubits];
        H(register[0]);
        for i in 0 .. numQubits - 2 {
            CNOT(register[i], register[i + 1]);
        }
        let results = MultiM(register);
        ResetAll(register);
        return results;
    }

    operation BellStatePreparation() : Result[] {
        use qubits = Qubit[2];
        H(qubits[0]);
        CNOT(qubits[0], qubits[1]);
        let results = MultiM(qubits);
        ResetAll(qubits);
        return results;
    }

    operation QuantumTeleportation(messageState : Result) : Result {
        use message = Qubit();
        if messageState == One {
            X(message);
        }
        use alice = Qubit();
        use bob = Qubit();
        H(alice);
        CNOT(alice, bob);
        CNOT(message, alice);
        H(message);
        let m1 = M(message);
        let m2 = M(alice);
        if m2 == One { X(bob); }
        if m1 == One { Z(bob); }
        let result = M(bob);
        ResetAll([message, alice, bob]);
        return result;
    }

    @EntryPoint()
    operation Main() : Unit {
        Message("JADED Q# Quantum Algorithms");
        Message("============================");
        Message("");
        Message("1. Grover's Algorithm:");
        let groverResults = GroverSearch(4, 7);
        Message($"   Marked state search results for 7 in 4 qubits: {groverResults}");
        Message("");
        Message("2. Bell State:");
        let bellResults = BellStatePreparation();
        Message($"   Bell state: {bellResults}");
        Message("");
        Message("3. Entanglement:");
        let entanglementResults = EntanglementCircuit(5);
        Message($"   Entangled state (5 qubits): {entanglementResults}");
        Message("");
        Message("4. Protein Folding Simulation:");
        let sequence = [1,2,3,4,5,6,7,8];
        let proteinResults = ProteinFoldingCircuit(sequence, 8);
        Message($"   Protein structure encoding: {proteinResults}");
        Message("");
        Message("5. Quantum Teleportation:");
        let tele0 = QuantumTeleportation(Zero);
        let tele1 = QuantumTeleportation(One);
        Message($"   Teleporting |0> resulted: {tele0}");
        Message($"   Teleporting |1> resulted: {tele1}");
        Message("");
        Message("All quantum algorithms executed successfully!");
    }
}

